import { useCallback, useEffect, useRef } from 'react';

// NASA EONET — free, no auth required
const EONET_URL  = 'https://eonet.gsfc.nasa.gov/api/v3/events?category=wildfires&status=open&limit=500';
const REFRESH_MS = 30 * 60_000; // 30 minutes

interface EonetGeometry {
  date:        string;
  type:        'Point';
  coordinates: [number, number]; // [lon, lat]
}

interface EonetEvent {
  id:       string;
  title:    string;
  geometry: EonetGeometry[];
}

interface EonetResponse {
  events: EonetEvent[];
}

function ageMs(dateStr: string): number {
  return Date.now() - new Date(dateStr).getTime();
}

function ageLabel(ms: number): string {
  const h = Math.round(ms / 3_600_000);
  if (h < 1)  return '< 1 h ago';
  if (h < 24) return `${h} h ago`;
  return `${Math.round(h / 24)} d ago`;
}

function fireTitle(raw: string): string {
  // strip leading "Wildfire - " prefix EONET adds
  return raw.replace(/^Wildfire\s*[-–]\s*/i, '');
}

interface FireLayerProps {
  map:     import('leaflet').Map | null;
  enabled: boolean;
}

export function FireLayer({ map, enabled }: FireLayerProps) {
  const markersRef = useRef<Map<string, import('leaflet').Marker>>(new Map());

  const clearAll = useCallback(() => {
    markersRef.current.forEach((m) => m.remove());
    markersRef.current.clear();
  }, []);

  const fetchAndRender = useCallback(async () => {
    if (!map || !enabled) return;

    try {
      const res = await fetch(EONET_URL);
      if (!res.ok || !map || !enabled) return;
      const data = await res.json() as EonetResponse;

      const L   = window.L;
      const seen = new Set<string>();

      for (const event of data.events) {
        // Use the most-recent geometry point
        const geom = event.geometry[event.geometry.length - 1];
        if (!geom || geom.type !== 'Point') continue;

        const [lon, lat] = geom.coordinates;
        seen.add(event.id);

        if (markersRef.current.has(event.id)) continue; // already on map

        const age     = ageMs(geom.date);
        const opacity = Math.max(0.4, 1 - age / (30 * 24 * 3_600_000));
        const name    = fireTitle(event.title);

        const icon = L.divIcon({
          html: `<div style="
            font-size:16px;line-height:1;
            opacity:${opacity.toFixed(2)};
            filter:drop-shadow(0 0 5px rgba(255,90,0,.85));
            cursor:pointer;
          ">🔥</div>`,
          className: '',
          iconSize:   [16, 16],
          iconAnchor: [8, 8],
        });

        const marker = L.marker([lat, lon], { icon });
        marker.bindPopup(`
          <div style="font-family:monospace;font-size:12px;line-height:1.75;min-width:185px;">
            <div style="font-weight:700;font-size:13px;color:#f85149;margin-bottom:4px">
              🔥 Wildfire
            </div>
            <div>📍 ${name}</div>
            <div>🕐 ${ageLabel(age)}</div>
            <div style="margin-top:4px;opacity:.6;font-size:10px">
              ${lat.toFixed(3)}°, ${lon.toFixed(3)}°
            </div>
          </div>`, { maxWidth: 240 });

        marker.addTo(map);
        markersRef.current.set(event.id, marker);
      }

      // Prune events that left the feed
      markersRef.current.forEach((m, id) => {
        if (!seen.has(id)) {
          m.remove();
          markersRef.current.delete(id);
        }
      });
    } catch {
      // network / rate-limit — ignore
    }
  }, [map, enabled]);

  useEffect(() => {
    if (!enabled) { clearAll(); return; }
    fetchAndRender();
    const id = setInterval(fetchAndRender, REFRESH_MS);
    return () => { clearInterval(id); clearAll(); };
  }, [enabled, fetchAndRender, clearAll]);

  return null;
}
